import {
  Injectable,
  InternalServerErrorException,
  Logger,
  NotFoundException,
} from '@nestjs/common';
import { CreateSmartleadDto } from './dto/create-smartlead.dto';
import { DatastoreService } from '../datastore/datastore.service';
import { StoreDataDto } from '../datastore/dto/store.dto';
import { documentType } from '../datastore/entites/documentType';
import { UsersService } from '../users/users.service';
import { SmartleadOpportunity } from './entities/smartlead.entity';
import { cache as cacheManager } from '../cacheStore';
import { SequenceWriterEnricherOutputDto } from '../enricher/entities/SequenceWriterEnricherInputDto';
import { SmartleadCampaignDto } from './dto/smartleadCampaign.dto';
import { SmartleadCampaign } from './entities/smartlead.campaign.entity';
import { OrchestratorService } from '../orchestrator/orchestrator.service';
import { SmartleadLeadDto } from './dto/smartlead-lead.dto';
import { generatePassword } from '../utils/generatePassword';
import { ClickupService } from '../clickup/clickup.service';

const TTL_3_DAYS = 259200;

@Injectable()
export class SmartleadService {
  private readonly logger = new Logger(SmartleadService.name);
  constructor(
    private readonly datastoreService: DatastoreService,
    private readonly usersService: UsersService,
    private readonly orchestratorService: OrchestratorService,
    private readonly clickupService: ClickupService,
  ) {}
  async createNewLead(
    createSmartleadDto: CreateSmartleadDto,
  ): Promise<{ message: string }> {
    try {
      this.logger.log('Loading Smartlead Service: Create New Lead');
      // Find OrgId by userId
      const orgId = this.usersService.findOrgIdForUser(
        createSmartleadDto.userId,
      );
      if (!orgId) {
        throw new NotFoundException('User not found');
      }
      const smartleadOpportunity = new SmartleadOpportunity({
        ...createSmartleadDto,
        id: createSmartleadDto.leadId,
        orgId,
        createdAt: new Date().toISOString(),
      });
      // See if lead already exists
      try {
        const lead = await this.getLeadById({
          id: createSmartleadDto.leadId,
          orgId,
        });
        if (lead) {
          return {
            message: 'Lead already exists',
          };
        }
      } catch (error) {
        if (error instanceof NotFoundException) {
          // Lead does not exist, so we can create it
        } else {
          throw error;
        }
      }
      await this.datastoreService.store(
        new StoreDataDto({
          data: smartleadOpportunity,
          context: { documentType: documentType.SMARTLEAD_OPPORTUNITY },
        }),
      );
      return {
        message: 'Lead created successfully',
      };
    } catch (error) {
      this.logger.error('Error in Smartlead Service: Create New Lead');
      this.logger.error(error);
      this.logger.error(`${JSON.stringify(createSmartleadDto)} Input Data`);
      throw error;
    }
  }

  async getLeadById({
    id,
    orgId,
  }: {
    id: string;
    orgId: string;
  }): Promise<SmartleadOpportunity> {
    const lead = await this.datastoreService.getById({
      id,
      documentType: documentType.SMARTLEAD_OPPORTUNITY,
    });
    if (lead?.data && lead?.data?.orgId !== orgId) {
      throw new NotFoundException('Lead not found');
    } else if (!lead?.data) {
      throw new NotFoundException('Lead not found');
    }
    return lead.data;
  }

  async getLeads(orgId: string): Promise<SmartleadOpportunity[]> {
    const leads = await this.datastoreService.getByField({
      documentType: documentType.SMARTLEAD_OPPORTUNITY,
      fieldKey: 'data.orgId',
      fieldValue: orgId,
    });
    return leads?.data;
  }

  async getLeadByEmail({
    email,
    orgId,
  }: {
    email: string;
    orgId: string;
  }): Promise<SmartleadOpportunity> {
    const apiKey = process.env.SMARTLEAD_REPORT_API_KEY;
    const cachedLead = await cacheManager.get(
      `getLeadByEmail-${orgId}-${email}`,
    );
    if (cachedLead) {
      this.logger.log(
        `Cached lead found for email: ${email} for org: ${orgId}`,
      );
      return JSON.parse(cachedLead);
    }
    this.logger.log(`Getting lead by email: ${email} for org: ${orgId}`);
    let res;
    try {
      res = await fetch(
        `https://server.smartlead.ai/api/v1/leads/?api_key=${apiKey}&email=${email}`,
      );

      const data = await res.json();
      const {
        id: smartleadId,
        first_name,
        last_name,
        website,
        created_at,
      } = data;
      this.logger.log(`Got Response`);
      const clientId =
        await this.usersService.findSmartleadClientIdForOrg(orgId);
      if (!clientId) {
        throw new NotFoundException('Client ID not found');
      }
      const filteredLeadCampaignData = data.lead_campaign_data.filter(
        (c) => c.client_id === parseInt(clientId),
      );
      //append all history to emailHistory, sorted by timestamp
      const historyDataRes = await Promise.all(
        filteredLeadCampaignData.map(async (c) => {
          const historyRes = await fetch(
            `https://server.smartlead.ai/api/v1/campaigns/${c?.campaign_id}/leads/${smartleadId}/message-history?api_key=${apiKey}`,
          );
          const historyData = await historyRes.json();
          return { historyData, campaignId: c?.campaign_name };
        }),
      );
      this.logger.log(`Got History Data`);
      const emailHistory = historyDataRes.reduce(
        (acc, { historyData, campaignId }) => {
          historyData?.history.forEach((item) => {
            acc.push({
              body: item.email_body,
              timestamp: item.time,
              campaignId: campaignId,
              subject: item.subject,
              type: item.type,
            });
          });
          return acc;
        },
        [],
      ) as Array<{
        body: string;
        timestamp: string;
        campaignId: string;
        subject: string;
        type: string;
      }>;
      this.logger.log(`Got Email History Length: ${emailHistory?.length}`);
      const sortedEmailHistory = emailHistory.sort((a, b) => {
        return (
          new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime()
        );
      });
      const returnedLeadVal = {
        id: smartleadId,
        firstName: first_name,
        lastName: last_name,
        email: email,
        company: website,
        emailHistory: sortedEmailHistory,
        orgId,
        createdAt: created_at,
        campaigns: data.lead_campaign_data.map((c) => c.campaign_name),
      };
      this.logger.log(`Got Returned Lead Val`);
      await cacheManager.set(
        `getLeadByEmail-${orgId}-${email}`,
        JSON.stringify(returnedLeadVal),
        TTL_3_DAYS,
      );
      this.logger.log(`Set Cache for ${orgId} and ${email}`);
      return returnedLeadVal;
    } catch (error) {
      this.logger.error('Error in Smartlead Service: Get Lead By Email');
      this.logger.error(error);
      if (res) {
        this.logger.error(`Response: ${res.status}`);
        this.logger.error(`Response: ${res.statusText}`);
        try {
          this.logger.error(`Response: ${await res.text()}`);
        } catch (error) {
          this.logger.error(`Error getting response text: ${error}`);
        }
      }
      throw error;
    }
  }

  /*

  */
  async getCampaignData(
    campaignId: string | number,
  ): Promise<SmartleadCampaignDto> {
