    return { message: 'Incremented successfully', id: this.id };
  }

  async incrementFailed(
    datastoreService: DatastoreService,
    amount: number,
  ): Promise<{ message: string; id: string }> {
    const incrementInput = {
      id: this.id,
      'data.failed': amount,
    };
    JobStatus.logger.log(`Incrementing failed for jobId: ${this.id}`);
    await datastoreService.increment(
      new IncrementDataDto({
        data: incrementInput,
        context: { documentType: documentType.JOB_STATUS },
      }),
    );
    return { message: 'Incremented successfully', id: this.id };
  }

  async delete(
    datastoreService: DatastoreService,
  ): Promise<{ message: string; id: string }> {
    await datastoreService.remove({
      id: this.id,
      documentType: documentType.JOB_STATUS,
    });
    return { message: 'Deleted successfully', id: this.id };
  }
}
