import {
  IsArray,
  IsNumber,
  IsOptional,
  IsString,
  Min,
} from 'class-validator';

/**
 * Number of days we assume a campaign runs for when it is not provided.
 */
export const DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN = 10;
/**
 * Number of emails a single warmed inbox is allowed to send per day.
 */
