export {
  DeliverabilityScoreBand,
  DeliverabilityScore,
  EmailAccountDeliverabilityScore,
  mapDeliverabilityScoreToBand,
} from '../entities/emailAccount.entity';

import {
  InternalServerErrorException,
  Logger,
  NotFoundException,
} from '@nestjs/common';
import { DatastoreService } from '../../datastore/datastore.service';
import { StoreDataDto } from '../../datastore/dto/store.dto';
import { documentType } from '../../datastore/entites/documentType';

/**
 * Deliverability bands an inbox can fall into. The band is derived from the
 * numeric warm up reputation (deliverability score) reported by smartlead.
 *
 * 100      -> High
 * 98 - 99  -> Medium
 * 95 - 97  -> Low
 * < 95     -> Burned
 * missing  -> Unknown
 */
export enum DeliverabilityScoreBand {
  High = 'High',
  Medium = 'Medium',
  Low = 'Low',
  Burned = 'Burned',
  Unknown = 'Unknown',
}

// Aliases kept around so consumers can refer to the band with the naming they
// are used to.
export const DeliverabilityScore = DeliverabilityScoreBand;
export type DeliverabilityScore = DeliverabilityScoreBand;
export const EmailAccountDeliverabilityScore = DeliverabilityScoreBand;
export type EmailAccountDeliverabilityScore = DeliverabilityScoreBand;
export const DeliverabilityBand = DeliverabilityScoreBand;
export type DeliverabilityBand = DeliverabilityScoreBand;

export const SMARTLEAD_EMAIL_ACCOUNTS_URL =
  'https://server.smartlead.ai/api/v1/email-accounts';

export const HIGH_DELIVERABILITY_SCORE = 100;
export const MEDIUM_DELIVERABILITY_SCORE = 98;
export const LOW_DELIVERABILITY_SCORE = 95;

/**
 * Parses a warm up reputation coming from smartlead. Smartlead returns either a
 * number (`100`) or a percentage string (`'100%'`).
 */
export function parseDeliverabilityScore(
  score?: number | string | null,
): number | undefined {
  if (score === null || score === undefined || score === '') {
    return undefined;
  }
  if (typeof score === 'number') {
    return Number.isFinite(score) ? score : undefined;
  }
  const parsed = parseFloat(`${score}`.replace('%', '').trim());
  return Number.isFinite(parsed) ? parsed : undefined;
}

/**
 * Maps the numeric deliverability score (warm up reputation) onto its band.
 */
export function mapDeliverabilityScoreToBand(
  score?: number | string | null,
): DeliverabilityScoreBand {
  const parsedScore = parseDeliverabilityScore(score);
  if (parsedScore === undefined) {
    return DeliverabilityScoreBand.Unknown;
  }
  if (parsedScore >= HIGH_DELIVERABILITY_SCORE) {
    return DeliverabilityScoreBand.High;
  }
  if (parsedScore >= MEDIUM_DELIVERABILITY_SCORE) {
    return DeliverabilityScoreBand.Medium;
  }
  if (parsedScore >= LOW_DELIVERABILITY_SCORE) {
    return DeliverabilityScoreBand.Low;
  }
  return DeliverabilityScoreBand.Burned;
}

/**
 * Derives the sending domain out of an email address.
 */
export function deriveDomainFromEmail(email?: string): string | undefined {
  if (!email || typeof email !== 'string') {
    return undefined;
  }
  const domain = email.includes('@') ? email.split('@').pop() : email;
  return domain ? domain.trim().toLowerCase() : undefined;
}

export type SmartleadInbox = {
  smartleadInboxId?: string;
  smartleadClientId?: string;
  email?: string;
  createdAt?: string;
  deliverabilityScore?: number;
  tags?: string[];
};

export type EmailAccountInput = Partial<EmailAccount> & Record<string, any>;

const toStringOrUndefined = (value: any): string | undefined => {
  if (value === null || value === undefined || value === '') {
    return undefined;
  }
  return `${value}`;
};

const toStringArray = (value: any): string[] => {
  if (value === null || value === undefined) {
    return [];
  }
  const list = Array.isArray(value) ? value : [value];
  const mapped = list
    .map((item) => {
      if (item === null || item === undefined) {
        return undefined;
      }
      if (typeof item === 'object') {
        return toStringOrUndefined(item?.name ?? item?.id ?? item?.tag);
      }
      return toStringOrUndefined(item);
    })
    .filter((item): item is string => Boolean(item));
  return Array.from(new Set(mapped));
};

/**
 * An email account (a warmed smartlead inbox) which can be assigned to a
 * campaign. It is keyed by its smartlead inbox id.
 */
export class EmailAccount {
  private static logger = new Logger(EmailAccount.name);

  smartleadInboxId: string;
  smartleadClientId: string;
  email: string;
  domain: string;
  tags: string[];
  campaignIds: string[];
  numberOfCampaignAssociated: number;
  /**
   * Numeric warm up reputation coming from smartlead.
   */
  deliverabilityScore: number;
  /**
   * The band the numeric deliverability score maps onto.
   */
  deliverabilityScoreBand: DeliverabilityScoreBand;
  createdAt: string;

  constructor(emailAccount: EmailAccountInput = {}) {
    const raw: Record<string, any> =
      emailAccount && (emailAccount as any).data
        ? (emailAccount as any).data
        : emailAccount ?? {};

    this.smartleadInboxId = toStringOrUndefined(
      raw.smartleadInboxId ?? raw.smartleadEmailAccountId ?? raw.id,
    );
    this.smartleadClientId = toStringOrUndefined(
      raw.smartleadClientId ?? raw.clientId ?? raw.client_id,
    );
    this.email = toStringOrUndefined(
      raw.email ?? raw.fromEmail ?? raw.from_email ?? raw.username,
    );
    this.domain =
      deriveDomainFromEmail(toStringOrUndefined(raw.domain)) ??
      deriveDomainFromEmail(this.email);
    this.tags = toStringArray(raw.tags);
    this.campaignIds = toStringArray(raw.campaignIds ?? raw.campaigns);
    this.numberOfCampaignAssociated = this.campaignIds.length;
    this.deliverabilityScore = parseDeliverabilityScore(
      raw.deliverabilityScore ??
        raw.warmupReputation ??
        raw.warmup_reputation ??
        raw?.warmupDetails?.warmupReputation ??
        raw?.warmup_details?.warmup_reputation,
    );
    this.deliverabilityScoreBand = mapDeliverabilityScoreToBand(
      this.deliverabilityScore,
    );
    this.createdAt = toStringOrUndefined(raw.createdAt ?? raw.created_at);
  }

  /**
   * The smartlead inbox id is the identity of an email account.
   */
  get id(): string {
    return this.smartleadInboxId;
  }
  set id(smartleadInboxId: string) {
    this.smartleadInboxId = toStringOrUndefined(smartleadInboxId);
  }
  /**
   * The deliverability score is the warm up reputation reported by smartlead.
   */
  get warmupReputation(): number {
    return this.deliverabilityScore;
  }
  get deliverabilityScoreCategory(): DeliverabilityScoreBand {
    return this.deliverabilityScoreBand;
  }
  get deliverabilityBand(): DeliverabilityScoreBand {
    return this.deliverabilityScoreBand;
  }
  get deliverabilityRating(): DeliverabilityScoreBand {
    return this.deliverabilityScoreBand;
  }
  get numberOfCampaignsAssociated(): number {
    return this.numberOfCampaignAssociated;
  }

  getDeliverabilityScoreBand(): DeliverabilityScoreBand {
    return mapDeliverabilityScoreToBand(this.deliverabilityScore);
  }

  static mapDeliverabilityScore(
    score?: number | string | null,
  ): DeliverabilityScoreBand {
    return mapDeliverabilityScoreToBand(score);
  }

  /**
   * Associates the account with a campaign. Returns true when the association
   * changed the account, false when the campaign was already associated (the
   * association is idempotent).
   */
  associateCampaign(campaignId: string): boolean {
    const id = toStringOrUndefined(campaignId);
    if (!id) {
      return false;
    }
    if (this.campaignIds.includes(id)) {
      return false;
    }
    this.campaignIds = [...this.campaignIds, id];
    this.numberOfCampaignAssociated = this.campaignIds.length;
    return true;
  }

  addCampaign(campaignId: string): boolean {
    return this.associateCampaign(campaignId);
  }

  /**
   * The number of *other* inboxes sharing the same sending domain.
   */
  numberOfOtherInboxesOnSameDomain(
    emailAccounts: Array<EmailAccount | EmailAccountInput>,
  ): number {
    return (emailAccounts ?? []).filter((account) => {
      const other =
        account instanceof EmailAccount ? account : new EmailAccount(account);
      return (
        other.smartleadInboxId !== this.smartleadInboxId &&
        Boolean(other.domain) &&
        other.domain === this.domain
      );
    }).length;
  }

  /**
   * Ranks inboxes so the best sending inboxes come first:
   * 1. deliverability score descending
   * 2. number of associated campaigns ascending
   * 3. number of other inboxes on the same domain ascending
   * 4. creation time ascending (oldest first)
   */
  static rankEmailAccounts(
    emailAccounts: Array<EmailAccount | EmailAccountInput>,
  ): EmailAccount[] {
    const accounts = (emailAccounts ?? []).map((account) =>
      account instanceof EmailAccount ? account : new EmailAccount(account),
    );
    const inboxesPerDomain = accounts.reduce<Record<string, number>>(
      (acc, account) => {
        const domain = account.domain ?? '';
        acc[domain] = (acc[domain] ?? 0) + 1;
        return acc;
      },
      {},
    );
    const otherInboxesOnDomain = (account: EmailAccount) =>
      account.domain ? (inboxesPerDomain[account.domain] ?? 1) - 1 : 0;
    const scoreOf = (account: EmailAccount) =>
      account.deliverabilityScore === undefined ||
      account.deliverabilityScore === null
        ? -1
        : account.deliverabilityScore;
    const createdAtOf = (account: EmailAccount) => {
      const time = account.createdAt
        ? new Date(account.createdAt).getTime()
        : NaN;
      return Number.isNaN(time) ? Number.POSITIVE_INFINITY : time;
    };

    return [...accounts].sort((a, b) => {
      const scoreDifference = scoreOf(b) - scoreOf(a);
      if (scoreDifference !== 0) {
        return scoreDifference;
      }
      const campaignDifference =
        a.numberOfCampaignAssociated - b.numberOfCampaignAssociated;
      if (campaignDifference !== 0) {
        return campaignDifference;
      }
      const domainDifference =
        otherInboxesOnDomain(a) - otherInboxesOnDomain(b);
      if (domainDifference !== 0) {
        return domainDifference;
      }
      const createdAtDifference = createdAtOf(a) - createdAtOf(b);
      if (Number.isNaN(createdAtDifference)) {
        return 0;
      }
      return createdAtDifference;
    });
  }

  static mapEmailAccount(item: any): EmailAccount {
    return item?.data ? new EmailAccount(item.data) : new EmailAccount(item);
  }

  private static toArray(data: any): any[] {
    if (!data) {
      return [];
    }
    return Array.isArray(data) ? data.filter(Boolean) : [data];
  }

  private static assertDatastore(datastoreService: DatastoreService) {
    if (!datastoreService) {
      throw new InternalServerErrorException(
        'Datastore service is not available for email accounts',
      );
    }
  }

  /**
   * Persists the email account inside of the email account datastore.
   */
  async save(datastoreService: DatastoreService): Promise<EmailAccount> {
    EmailAccount.assertDatastore(datastoreService);
    if (!this.smartleadInboxId) {
      throw new InternalServerErrorException(
        'Cannot save an email account without a smartleadInboxId',
      );
    }
    EmailAccount.logger.log(
      `Saving email account: ${this.smartleadInboxId} (${this.email})`,
    );
    await datastoreService.store(
      new StoreDataDto({
        data: this.toJSON(),
        context: {
          documentType: documentType.EMAIL_ACCOUNT,
          uniqueId: this.smartleadInboxId,
        },
      }),
    );
    return this;
  }

  toJSON(): Record<string, any> {
    return {
      smartleadInboxId: this.smartleadInboxId,
      smartleadClientId: this.smartleadClientId,
      email: this.email,
      domain: this.domain,
      tags: this.tags,
      campaignIds: this.campaignIds,
      numberOfCampaignAssociated: this.numberOfCampaignAssociated,
      deliverabilityScore: this.deliverabilityScore,
      deliverabilityScoreBand: this.deliverabilityScoreBand,
      createdAt: this.createdAt,
    };
  }

  static async create(
    emailAccount: EmailAccountInput,
    datastoreService: DatastoreService,
  ): Promise<EmailAccount> {
    return new EmailAccount(emailAccount).save(datastoreService);
  }

  private static async findByField(
    fieldKey: string,
    fieldValue: any,
    datastoreService: DatastoreService,
    pagination?: { page: number; pageSize: number },
  ): Promise<EmailAccount[]> {
    EmailAccount.assertDatastore(datastoreService);
    const res = await datastoreService.getByField({
      fieldKey,
      fieldValue,
      documentType: documentType.EMAIL_ACCOUNT,
      ...(pagination ? { pagination } : {}),
    });
    return EmailAccount.toArray(res?.data).map(EmailAccount.mapEmailAccount);
  }

  /**
   * Finds an email account by its smartlead inbox id. Returns null when the
   * inbox is not stored yet.
   */
  static async findBySmartleadInboxId(
    smartleadInboxId: string,
    datastoreService: DatastoreService,
  ): Promise<EmailAccount | null> {
    const id = toStringOrUndefined(smartleadInboxId);
    if (!id) {
      return null;
    }
    const accounts = await EmailAccount.findByField(
      'data.smartleadInboxId',
      id,
      datastoreService,
    );
    if (accounts.length > 0) {
      return accounts[0];
    }
    // Fall back onto the document id, the inbox id is used as the unique id.
    try {
      if (typeof datastoreService?.getById === 'function') {
        const res = await datastoreService.getById({
          id,
          documentType: documentType.EMAIL_ACCOUNT,
        });
        const found = EmailAccount.toArray(res?.data)[0];
        if (found) {
          return EmailAccount.mapEmailAccount(found);
        }
      }
    } catch (error) {
      EmailAccount.logger.warn(
        `Unable to look up email account ${id} by document id: ${error}`,
      );
    }
    return null;
  }

  static async findById(
    smartleadInboxId: string,
    datastoreService: DatastoreService,
  ): Promise<EmailAccount | null> {
    return EmailAccount.findBySmartleadInboxId(
      smartleadInboxId,
      datastoreService,
    );
  }

  static async findByEmail(
    email: string,
    datastoreService: DatastoreService,
  ): Promise<EmailAccount | null> {
    const accounts = await EmailAccount.findByField(
      'data.email',
      email,
      datastoreService,
    );
    return accounts.length > 0 ? accounts[0] : null;
  }

  static async findBySmartleadClientId(
    smartleadClientId: string,
    datastoreService: DatastoreService,
    pagination?: { page: number; pageSize: number },
  ): Promise<EmailAccount[]> {
    return EmailAccount.findByField(
      'data.smartleadClientId',
      toStringOrUndefined(smartleadClientId),
      datastoreService,
      pagination,
    );
  }

  static async findAll(
    datastoreService: DatastoreService,
    pagination?: { page: number; pageSize: number },
  ): Promise<EmailAccount[]> {
    return EmailAccount.findByField(
      'data.smartleadInboxId',
      { $exists: true },
      datastoreService,
      pagination,
    );
  }

  async delete(
    datastoreService: DatastoreService,
  ): Promise<{ message: string; smartleadInboxId: string }> {
    return EmailAccount.remove(this.smartleadInboxId, datastoreService);
  }

  static async remove(
    smartleadInboxId: string,
    datastoreService: DatastoreService,
  ): Promise<{ message: string; smartleadInboxId: string }> {
    EmailAccount.assertDatastore(datastoreService);
    const id = toStringOrUndefined(smartleadInboxId);
    EmailAccount.logger.log(`Deleting email account: ${id}`);
    await datastoreService.remove({
      id,
      documentType: documentType.EMAIL_ACCOUNT,
    });
    return {
      message: 'Email account deleted successfully',
      smartleadInboxId: id,
    };
  }

  /**
   * Pulls the inbox out of a smartlead response. Smartlead either returns the
   * inbox itself or the list of all the inboxes.
   */
  private static extractRemoteInbox(
    payload: any,
    smartleadInboxId: string,
  ): Record<string, any> | null {
    if (!payload) {
      return null;
    }
    if (payload?.ok === false) {
      return null;
    }
    const candidates = Array.isArray(payload)
      ? payload
      : Array.isArray(payload?.data)
        ? payload.data
        : Array.isArray(payload?.email_accounts)
          ? payload.email_accounts
          : [payload];
    const matched = candidates.find(
      (candidate) =>
        candidate &&
        toStringOrUndefined(candidate?.id ?? candidate?.smartleadInboxId) ===
          toStringOrUndefined(smartleadInboxId),
    );
    if (matched) {
      return matched;
    }
    // A single inbox payload does not always carry the id back.
    if (
      candidates.length === 1 &&
      candidates[0] &&
      typeof candidates[0] === 'object' &&
      !Array.isArray(candidates[0]) &&
      !candidates[0]?.id &&
      !candidates[0]?.smartleadInboxId &&
      Object.keys(candidates[0]).some((key) =>
        [
          'created_at',
          'createdAt',
          'warmup_details',
          'warmupDetails',
          'warmup_reputation',
          'warmupReputation',
          'from_email',
          'email',
        ].includes(key),
      )
    ) {
      return candidates[0];
    }
    return null;
  }

  /**
   * Reads the inbox from smartlead so the creation time and the warm up
   * reputation can be hydrated. Throws a NotFoundException when the inbox does
   * not exist inside of smartlead.
   */
  static async getSmartleadInbox(
    smartleadInboxId: string,
    apiKey: string = process.env.SMARTLEAD_REPORT_API_KEY,
  ): Promise<SmartleadInbox> {
    const id = toStringOrUndefined(smartleadInboxId);
    if (!id) {
      throw new NotFoundException('Email account not found in smartlead');
    }
    EmailAccount.logger.log(`Getting smartlead inbox: ${id}`);
    let res: Response;
    try {
      res = await fetch(`${SMARTLEAD_EMAIL_ACCOUNTS_URL}/${id}?api_key=${apiKey}`);
    } catch (error) {
      EmailAccount.logger.error(
        `Failed to reach smartlead for inbox ${id}: ${error}`,
      );
      throw new InternalServerErrorException(
        `Failed to get the email account ${id} from smartlead`,
      );
    }
    if (!res || res.status === 404) {
      throw new NotFoundException(`Email account not found in smartlead: ${id}`);
    }
    if (res.ok === false) {
      EmailAccount.logger.error(
        `Failed to get smartlead inbox ${id}: ${res.status}`,
      );
      throw new InternalServerErrorException(
        `Failed to get the email account ${id} from smartlead`,
      );
    }
    let payload: any;
    try {
      payload = await res.json();
    } catch (error) {
      EmailAccount.logger.error(
        `Failed to parse the smartlead response for inbox ${id}: ${error}`,
      );
      throw new NotFoundException(`Email account not found in smartlead: ${id}`);
    }
    const remoteInbox = EmailAccount.extractRemoteInbox(payload, id);
    if (!remoteInbox) {
      throw new NotFoundException(`Email account not found in smartlead: ${id}`);
    }
    return {
      smartleadInboxId: id,
      smartleadClientId: toStringOrUndefined(
        remoteInbox?.client_id ?? remoteInbox?.clientId,
      ),
      email: toStringOrUndefined(
        remoteInbox?.from_email ?? remoteInbox?.email ?? remoteInbox?.username,
      ),
      createdAt: toStringOrUndefined(
        remoteInbox?.created_at ?? remoteInbox?.createdAt,
      ),
      deliverabilityScore: parseDeliverabilityScore(
        remoteInbox?.warmup_details?.warmup_reputation ??
          remoteInbox?.warmupDetails?.warmupReputation ??
          remoteInbox?.warmup_reputation ??
          remoteInbox?.warmupReputation ??
          remoteInbox?.deliverabilityScore,
      ),
      tags: toStringArray(remoteInbox?.tags),
    };
  }
}

