import {
  BadRequestException,
  Injectable,
  InternalServerErrorException,
  Logger,
  NotFoundException,
  Optional,
} from '@nestjs/common';
import { DatastoreService } from '../datastore/datastore.service';
import {
  AssociateEmailAccountsWithCampaignDto,
  DEFAULT_EMAIL_ACCOUNT_PAGE,
  DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE,
  DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN,
  DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY,
  EmailAccountDto,
  EmailAccountListDto,
  EmailAccountPaginationDto,
} from './dto/emailAccount.dto';
import { EmailAccount, EmailAccountInput } from './entities/emailAccount.entity';

type EmailAccountReference = EmailAccountInput | string;

@Injectable()
export class EmailinfraService {
  private readonly logger = new Logger(EmailinfraService.name);

  constructor(
    @Optional() private readonly datastoreService?: DatastoreService,
  ) {}

  private get datastore(): DatastoreService {
    if (!this.datastoreService) {
      throw new InternalServerErrorException(
        'Datastore service is not available for email accounts',
      );
    }
    return this.datastoreService;
  }

  private static normalizePagination(
    pagination?: EmailAccountPaginationDto | number,
    pageSize?: number,
  ): { page: number; pageSize: number } {
    if (typeof pagination === 'number' || typeof pageSize === 'number') {
      return {
        page:
          typeof pagination === 'number' ? pagination : DEFAULT_EMAIL_ACCOUNT_PAGE,
        pageSize:
          typeof pageSize === 'number'
            ? pageSize
            : DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE,
      };
    }
    return {
      page: pagination?.page ?? DEFAULT_EMAIL_ACCOUNT_PAGE,
      pageSize: pagination?.pageSize ?? DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE,
    };
  }

  /**
   * The datastore already applies the pagination, this only kicks in when more
   * than a single page came back.
   */
  private static applyPagination(
    emailAccounts: EmailAccount[],
    { page, pageSize }: { page: number; pageSize: number },
  ): EmailAccount[] {
    if (!pageSize || emailAccounts.length <= pageSize) {
      return emailAccounts;
    }
    const start = page * pageSize;
    return emailAccounts.slice(start, start + pageSize);
  }

  private static resolveSmartleadInboxId(
    emailAccount: EmailAccountReference,
  ): string {
    if (!emailAccount) {
      return undefined;
    }
    if (typeof emailAccount === 'string' || typeof emailAccount === 'number') {
      return `${emailAccount}`;
    }
    const smartleadInboxId =
      emailAccount?.smartleadInboxId ?? (emailAccount as any)?.id;
    return smartleadInboxId ? `${smartleadInboxId}` : undefined;
  }

  /**
   * Given the total number of emails to send we work out how many inboxes are
   * needed and return the best ranked inboxes of the smartlead client.
   *
   * required inboxes = floor(total emails / campaign days / emails per inbox per day)
   *
   * Example:
   *  600 emails to send, 10 days in the campaign, 20 emails per inbox per day
   *  -> floor(600 / 10 / 20) = 3 inboxes
   *
   * The inboxes are ranked by:
   *  1. deliverability score (warm up reputation) descending
   *  2. number of campaigns already associated ascending
   *  3. number of other inboxes on the same domain ascending
   *  4. creation time ascending (oldest inboxes first)
   */
  async getBestEmailAccountsForCampaign({
    smartleadClientId,
    campaignId,
    numberOfDaysInCampaign = DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN,
    totalNumberOfEmailsToSend,
    numberOfEmailsPerInboxPerDay = DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY,
  }: EmailAccountListDto): Promise<EmailAccount[]> {
    if (!smartleadClientId) {
      throw new BadRequestException('smartleadClientId is required');
    }
    const numberOfEmailAccountsNeeded = this.getNumberOfEmailAccountsNeeded({
      totalNumberOfEmailsToSend,
      numberOfDaysInCampaign,
      numberOfEmailsPerInboxPerDay,
    });
    this.logger.log(
      `Campaign ${campaignId} for smartlead client ${smartleadClientId} needs ${numberOfEmailAccountsNeeded} inboxes for ${totalNumberOfEmailsToSend} emails over ${numberOfDaysInCampaign} days`,
    );
    if (numberOfEmailAccountsNeeded <= 0) {
      return [];
    }
    const emailAccounts = await EmailAccount.findBySmartleadClientId(
      smartleadClientId,
      this.datastore,
    );
    if (emailAccounts.length === 0) {
      this.logger.warn(
        `No email accounts found for smartlead client: ${smartleadClientId}`,
      );
      return [];
    }
    const rankedEmailAccounts = EmailAccount.rankEmailAccounts(emailAccounts);
    if (rankedEmailAccounts.length < numberOfEmailAccountsNeeded) {
      this.logger.warn(
        `Only ${rankedEmailAccounts.length} inboxes available for smartlead client ${smartleadClientId}, ${numberOfEmailAccountsNeeded} were needed`,
      );
    }
    return rankedEmailAccounts.slice(0, numberOfEmailAccountsNeeded);
  }

  /**
   * floor(total emails / campaign days / emails per inbox per day)
   */
  getNumberOfEmailAccountsNeeded({
    totalNumberOfEmailsToSend,
    numberOfDaysInCampaign = DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN,
    numberOfEmailsPerInboxPerDay = DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY,
  }: {
    totalNumberOfEmailsToSend: number;
    numberOfDaysInCampaign?: number;
    numberOfEmailsPerInboxPerDay?: number;
  }): number {
    const days = numberOfDaysInCampaign || DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN;
    const emailsPerInboxPerDay =
      numberOfEmailsPerInboxPerDay ||
      DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY;
    if (!totalNumberOfEmailsToSend || totalNumberOfEmailsToSend <= 0) {
      return 0;
    }
    return Math.floor(totalNumberOfEmailsToSend / days / emailsPerInboxPerDay);
  }

  /**
   * Associates the inboxes with a campaign. Duplicated inbox ids are treated as
   * a single inbox and the association is idempotent. When any of the requested
   * inboxes does not exist nothing is written at all.
   */
  async associateEmailAccountsWithCampaign({
    emailAccountIds,
    campaignId,
  }: AssociateEmailAccountsWithCampaignDto): Promise<EmailAccount[]> {
    if (!campaignId) {
      throw new BadRequestException('campaignId is required');
    }
    const uniqueEmailAccountIds = Array.from(
      new Set(
        (emailAccountIds ?? [])
          .filter(
            (emailAccountId) =>
              emailAccountId !== null &&
              emailAccountId !== undefined &&
              `${emailAccountId}` !== '',
          )
          .map((emailAccountId) => `${emailAccountId}`),
      ),
    );
    if (uniqueEmailAccountIds.length === 0) {
      throw new BadRequestException('emailAccountIds is required');
    }
    this.logger.log(
      `Associating ${uniqueEmailAccountIds.length} email accounts with campaign: ${campaignId}`,
    );
    // Load every inbox up front so nothing is written when one of them is
    // missing.
    const emailAccounts = await Promise.all(
      uniqueEmailAccountIds.map((emailAccountId) =>
        EmailAccount.findBySmartleadInboxId(emailAccountId, this.datastore),
      ),
    );
    const missingEmailAccountIds = uniqueEmailAccountIds.filter(
      (emailAccountId, index) => !emailAccounts[index],
    );
    if (missingEmailAccountIds.length > 0) {
      this.logger.error(
        `Email accounts not found: ${missingEmailAccountIds.join(', ')}`,
      );
      throw new NotFoundException(
        `Email accounts not found: ${missingEmailAccountIds.join(', ')}`,
      );
    }
    const associatedEmailAccounts: EmailAccount[] = [];
    for (const emailAccount of emailAccounts) {
      const changed = emailAccount.associateCampaign(campaignId);
      if (changed) {
        await emailAccount.save(this.datastore);
      } else {
        this.logger.log(
          `Email account ${emailAccount.smartleadInboxId} is already associated with campaign: ${campaignId}`,
        );
      }
      associatedEmailAccounts.push(emailAccount);
    }
    return associatedEmailAccounts;
  }

  /**
   * Saves the inbox, hydrating the creation time and the warm up reputation
   * (deliverability score) from smartlead.
   */
  async saveEmailAccount(emailAccount: EmailAccountDto): Promise<EmailAccount> {
    const smartleadInboxId =
      EmailinfraService.resolveSmartleadInboxId(emailAccount);
    if (!smartleadInboxId) {
      throw new BadRequestException('smartleadInboxId is required');
    }
    const smartleadInbox = await EmailAccount.getSmartleadInbox(
      smartleadInboxId,
    );
    let existingEmailAccount: EmailAccount = null;
    try {
      existingEmailAccount = await EmailAccount.findBySmartleadInboxId(
        smartleadInboxId,
        this.datastore,
      );
    } catch (error) {
      this.logger.warn(
        `Unable to read the existing email account ${smartleadInboxId}: ${error}`,
      );
    }
    const hydratedEmailAccount = new EmailAccount({
      ...(existingEmailAccount ? existingEmailAccount.toJSON() : {}),
      ...emailAccount,
      smartleadInboxId,
      email:
        emailAccount?.email ??
        existingEmailAccount?.email ??
        smartleadInbox?.email,
      smartleadClientId:
        emailAccount?.smartleadClientId ??
        existingEmailAccount?.smartleadClientId ??
        smartleadInbox?.smartleadClientId,
      tags:
        emailAccount?.tags ??
        existingEmailAccount?.tags ??
        smartleadInbox?.tags ??
        [],
      campaignIds:
        emailAccount?.campaignIds ?? existingEmailAccount?.campaignIds ?? [],
      createdAt:
        smartleadInbox?.createdAt ??
        existingEmailAccount?.createdAt ??
        new Date().toISOString(),
      deliverabilityScore: smartleadInbox?.deliverabilityScore,
    });
    return hydratedEmailAccount.save(this.datastore);
  }

  createEmailAccount(emailAccount: EmailAccountDto): Promise<EmailAccount> {
    return this.saveEmailAccount(emailAccount);
  }

  /**
   * Reads an email account by its smartlead inbox id (or by email when only an
   * email is handed over).
   */
  async getEmailAccount(
    emailAccount: EmailAccountReference,
  ): Promise<EmailAccount> {
    const smartleadInboxId =
      EmailinfraService.resolveSmartleadInboxId(emailAccount);
    if (!smartleadInboxId) {
      const email =
        typeof emailAccount === 'object' ? emailAccount?.email : undefined;
      if (email) {
        return this.getEmailAccountByEmail(email);
      }
      throw new BadRequestException('smartleadInboxId is required');
    }
    const found = await EmailAccount.findBySmartleadInboxId(
      smartleadInboxId,
      this.datastore,
    );
    if (!found) {
      throw new NotFoundException(
        `Email account not found: ${smartleadInboxId}`,
      );
    }
    return found;
  }

  getEmailAccountById(smartleadInboxId: string): Promise<EmailAccount> {
    return this.getEmailAccount(smartleadInboxId);
  }

  getEmailAccountBySmartleadInboxId(
    smartleadInboxId: string,
  ): Promise<EmailAccount> {
    return this.getEmailAccount(smartleadInboxId);
  }

  /**
   * Paginated list of every email account.
   */
  async getAllEmailAccounts(
    pagination?: EmailAccountPaginationDto | number,
    pageSize?: number,
  ): Promise<EmailAccount[]> {
    const normalizedPagination = EmailinfraService.normalizePagination(
      pagination,
      pageSize,
    );
    const emailAccounts = await EmailAccount.findAll(
      this.datastore,
      normalizedPagination,
    );
    return EmailinfraService.applyPagination(
      emailAccounts,
      normalizedPagination,
    );
  }

  listEmailAccounts(
    pagination?: EmailAccountPaginationDto | number,
    pageSize?: number,
  ): Promise<EmailAccount[]> {
    return this.getAllEmailAccounts(pagination, pageSize);
  }

  async getEmailAccountByEmail(email: string): Promise<EmailAccount> {
    if (!email) {
      throw new BadRequestException('email is required');
    }
    const found = await EmailAccount.findByEmail(email, this.datastore);
    if (!found) {
      throw new NotFoundException(`Email account not found: ${email}`);
    }
    return found;
  }

  /**
   * Every inbox belonging to a smartlead client.
   */
  async getEmailAccountBySmartleadClientId(
    smartleadClientId: string,
    pagination?: EmailAccountPaginationDto,
  ): Promise<EmailAccount[]> {
    if (!smartleadClientId) {
      throw new BadRequestException('smartleadClientId is required');
    }
    return EmailAccount.findBySmartleadClientId(
      smartleadClientId,
      this.datastore,
      pagination
        ? EmailinfraService.normalizePagination(pagination)
        : undefined,
    );
  }

  getEmailAccountsBySmartleadClientId(
    smartleadClientId: string,
    pagination?: EmailAccountPaginationDto,
  ): Promise<EmailAccount[]> {
    return this.getEmailAccountBySmartleadClientId(
      smartleadClientId,
      pagination,
    );
  }

  async deleteEmailAccount(
    emailAccount: EmailAccountReference,
  ): Promise<{ message: string; smartleadInboxId: string }> {
    const smartleadInboxId =
      EmailinfraService.resolveSmartleadInboxId(emailAccount);
    if (!smartleadInboxId) {
      throw new BadRequestException('smartleadInboxId is required');
    }
    const existingEmailAccount = await EmailAccount.findBySmartleadInboxId(
      smartleadInboxId,
      this.datastore,
    );
    if (!existingEmailAccount) {
      throw new NotFoundException(
        `Email account not found: ${smartleadInboxId}`,
      );
    }
    return existingEmailAccount.delete(this.datastore);
  }

  /**
   * Re-reads the warm up reputation of an inbox from smartlead and stores it.
   * Used by the reputation sync script.
   */
  async syncEmailAccountReputation(
    smartleadInboxId: string,
  ): Promise<EmailAccount> {
    const emailAccount = await this.getEmailAccount(smartleadInboxId);
    return this.saveEmailAccount({
      ...emailAccount.toJSON(),
      smartleadInboxId: emailAccount.smartleadInboxId,
    } as EmailAccountDto);
  }
}

import {
  Body,
  Controller,
  Delete,
  Get,
  Param,
  Post,
  Query,
  UseGuards,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { EmailinfraService } from './emailinfra.service';
import {
  AssociateEmailAccountsWithCampaignDto,
  EmailAccountDto,
  EmailAccountListDto,
} from './dto/emailAccount.dto';

@Controller('emailinfra')
export class EmailinfraController {
  constructor(private readonly emailinfraService: EmailinfraService) {}

  @UseGuards(AuthGuard('api-key'))
  @Post('email-accounts')
  saveEmailAccount(@Body() emailAccount: EmailAccountDto) {
    return this.emailinfraService.saveEmailAccount(emailAccount);
  }

  @UseGuards(AuthGuard('api-key'))
  @Get('email-accounts')
  getAllEmailAccounts(
    @Query('page') page?: string,
    @Query('pageSize') pageSize?: string,
  ) {
    return this.emailinfraService.getAllEmailAccounts({
      page: page ? parseInt(page, 10) : undefined,
      pageSize: pageSize ? parseInt(pageSize, 10) : undefined,
    });
  }

  @UseGuards(AuthGuard('api-key'))
  @Post('email-accounts/campaign')
  associateEmailAccountsWithCampaign(
    @Body()
    associateEmailAccountsWithCampaignDto: AssociateEmailAccountsWithCampaignDto,
  ) {
    return this.emailinfraService.associateEmailAccountsWithCampaign(
      associateEmailAccountsWithCampaignDto,
    );
  }

  @UseGuards(AuthGuard('api-key'))
  @Post('email-accounts/best')
  getBestEmailAccountsForCampaign(
    @Body() emailAccountListDto: EmailAccountListDto,
  ) {
    return this.emailinfraService.getBestEmailAccountsForCampaign(
      emailAccountListDto,
    );
  }

  @UseGuards(AuthGuard('api-key'))
  @Get('email-accounts/email/:email')
  getEmailAccountByEmail(@Param('email') email: string) {
    return this.emailinfraService.getEmailAccountByEmail(email);
  }

  @UseGuards(AuthGuard('api-key'))
  @Get('email-accounts/client/:smartleadClientId')
  getEmailAccountBySmartleadClientId(
    @Param('smartleadClientId') smartleadClientId: string,
    @Query('page') page?: string,
    @Query('pageSize') pageSize?: string,
  ) {
    return this.emailinfraService.getEmailAccountBySmartleadClientId(
      smartleadClientId,
      page || pageSize
        ? {
            page: page ? parseInt(page, 10) : undefined,
            pageSize: pageSize ? parseInt(pageSize, 10) : undefined,
          }
        : undefined,
    );
  }

  @UseGuards(AuthGuard('api-key'))
  @Get('email-accounts/:smartleadInboxId')
  getEmailAccount(@Param('smartleadInboxId') smartleadInboxId: string) {
    return this.emailinfraService.getEmailAccount(smartleadInboxId);
  }

  @UseGuards(AuthGuard('api-key'))
  @Delete('email-accounts/:smartleadInboxId')
  deleteEmailAccount(@Param('smartleadInboxId') smartleadInboxId: string) {
    return this.emailinfraService.deleteEmailAccount(smartleadInboxId);
  }
}

import { Module } from '@nestjs/common';
import { EmailinfraService } from './emailinfra.service';
import { EmailinfraController } from './emailinfra.controller';
import { DatastoreModule } from '../datastore/datastore.module';

@Module({
  controllers: [EmailinfraController],
  providers: [EmailinfraService],
  exports: [EmailinfraService],
  imports: [DatastoreModule],
})
export class EmailinfraModule {}

import { Test, TestingModule } from '@nestjs/testing';
import { NotFoundException } from '@nestjs/common';
import { EmailinfraService } from './emailinfra.service';
import { DatastoreService } from '../datastore/datastore.service';
import { documentType } from '../datastore/entites/documentType';
import {
  DeliverabilityScoreBand,
  EmailAccount,
  mapDeliverabilityScoreToBand,
} from './entities/emailAccount.entity';

/**
 * Minimal in memory replacement of the datastore so the email account
 * behaviour can be asserted end to end.
 */
class InMemoryDatastore {
  documents = new Map<string, Record<string, any>>();

  store = jest.fn(async ({ data, context }: any) => {
    expect(context.documentType).toBe(documentType.EMAIL_ACCOUNT);
    this.documents.set(context.uniqueId, JSON.parse(JSON.stringify(data)));
    return { message: 'Data stored successfully', uniqueId: context.uniqueId };
  });

  getById = jest.fn(async ({ id }: any) => {
    return { data: this.documents.get(id), message: 'ok' };
  });

  getByField = jest.fn(async ({ fieldKey, fieldValue, pagination }: any) => {
    const key = fieldKey.replace('data.', '');
    let found = [...this.documents.values()].filter((doc) => {
      if (fieldValue && fieldValue.$exists) {
        return doc[key] !== undefined;
      }
      return doc[key] === fieldValue;
    });
    if (pagination) {
      const { page, pageSize } = pagination;
      found = found.slice(page * pageSize, page * pageSize + pageSize);
    }
    return { data: found.length > 0 ? found : undefined, message: 'ok' };
  });

  remove = jest.fn(async ({ id }: any) => {
    this.documents.delete(id);
    return { message: 'Data removed successfully' };
  });
}

const smartleadInbox = ({
  id,
  email,
  createdAt = '2024-01-01T00:00:00.000Z',
  warmupReputation = '100%',
}: {
  id: string;
  email: string;
  createdAt?: string;
  warmupReputation?: string | number;
}) => ({
  id: parseInt(id, 10),
  created_at: createdAt,
  from_email: email,
  warmup_details: { warmup_reputation: warmupReputation },
});

describe('EmailinfraService', () => {
  let service: EmailinfraService;
  let datastore: InMemoryDatastore;

  beforeEach(async () => {
    datastore = new InMemoryDatastore();
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        EmailinfraService,
        { provide: DatastoreService, useValue: datastore },
      ],
    }).compile();
    service = module.get<EmailinfraService>(EmailinfraService);
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  const mockSmartleadInboxes = (inboxes: Array<Record<string, any>>) => {
    global.fetch = jest.fn(async (url: any) => {
      const id = `${url}`.split('/').pop().split('?')[0];
      const inbox = inboxes.find((item) => `${item.id}` === id);
      if (!inbox) {
        return { ok: false, status: 404, json: async () => ({ ok: false }) };
      }
      return { ok: true, status: 200, json: async () => inbox };
    }) as any;
  };

  const saveInbox = async ({
    id,
    email,
    smartleadClientId = 'client-1',
    createdAt,
    warmupReputation,
    tags,
  }: {
    id: string;
    email: string;
    smartleadClientId?: string;
    createdAt?: string;
    warmupReputation?: string | number;
    tags?: string[];
  }) => {
    mockSmartleadInboxes([
      smartleadInbox({ id, email, createdAt, warmupReputation }),
    ]);
    return service.saveEmailAccount({
      smartleadInboxId: id,
      email,
      smartleadClientId,
      tags,
    });
  };

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  it('maps the deliverability score onto its band', () => {
    expect(mapDeliverabilityScoreToBand(100)).toBe(
      DeliverabilityScoreBand.High,
    );
    expect(mapDeliverabilityScoreToBand(99)).toBe(
      DeliverabilityScoreBand.Medium,
    );
    expect(mapDeliverabilityScoreToBand(98)).toBe(
      DeliverabilityScoreBand.Medium,
    );
    expect(mapDeliverabilityScoreToBand(97)).toBe(DeliverabilityScoreBand.Low);
    expect(mapDeliverabilityScoreToBand(95)).toBe(DeliverabilityScoreBand.Low);
    expect(mapDeliverabilityScoreToBand(94)).toBe(
      DeliverabilityScoreBand.Burned,
    );
    expect(mapDeliverabilityScoreToBand(0)).toBe(
      DeliverabilityScoreBand.Burned,
    );
    expect(mapDeliverabilityScoreToBand(undefined)).toBe(
      DeliverabilityScoreBand.Unknown,
    );
    expect(mapDeliverabilityScoreToBand(null)).toBe(
      DeliverabilityScoreBand.Unknown,
    );
  });

  it('hydrates the created at and warm up reputation from smartlead on save', async () => {
    const emailAccount = await saveInbox({
      id: '1',
      email: 'sender@Sending-Domain.com',
      warmupReputation: '96%',
      createdAt: '2023-05-05T00:00:00.000Z',
      tags: ['warm', 'warm'],
    });

    expect(emailAccount.smartleadInboxId).toBe('1');
    expect(emailAccount.smartleadClientId).toBe('client-1');
    expect(emailAccount.email).toBe('sender@Sending-Domain.com');
    expect(emailAccount.domain).toBe('sending-domain.com');
    expect(emailAccount.tags).toEqual(['warm']);
    expect(emailAccount.campaignIds).toEqual([]);
    expect(emailAccount.numberOfCampaignAssociated).toBe(0);
    expect(emailAccount.createdAt).toBe('2023-05-05T00:00:00.000Z');
    expect(emailAccount.deliverabilityScore).toBe(96);
    expect(emailAccount.deliverabilityScoreBand).toBe(
      DeliverabilityScoreBand.Low,
    );
    expect(datastore.documents.get('1').deliverabilityScore).toBe(96);
  });

  it('returns not found when the inbox does not exist inside of smartlead', async () => {
    mockSmartleadInboxes([]);
    await expect(
      service.saveEmailAccount({
        smartleadInboxId: '404',
        email: 'nope@domain.com',
        smartleadClientId: 'client-1',
      }),
    ).rejects.toThrow(NotFoundException);
    expect(datastore.store).not.toHaveBeenCalled();
  });

  it('marks a missing warm up reputation as unknown', async () => {
    global.fetch = jest.fn(async () => ({
      ok: true,
      status: 200,
      json: async () => ({ id: 7, created_at: '2024-01-01T00:00:00.000Z' }),
    })) as any;
    const emailAccount = await service.saveEmailAccount({
      smartleadInboxId: '7',
      email: 'seven@domain.com',
      smartleadClientId: 'client-1',
    });
    expect(emailAccount.deliverabilityScore).toBeUndefined();
    expect(emailAccount.deliverabilityScoreBand).toBe(
      DeliverabilityScoreBand.Unknown,
    );
  });

  it('looks accounts up by id, email and smartlead client', async () => {
    await saveInbox({ id: '1', email: 'one@domain-a.com' });
    await saveInbox({ id: '2', email: 'two@domain-b.com' });
    await saveInbox({
      id: '3',
      email: 'three@domain-c.com',
      smartleadClientId: 'client-2',
    });

    expect((await service.getEmailAccount('1')).email).toBe('one@domain-a.com');
    expect((await service.getEmailAccountByEmail('two@domain-b.com')).smartleadInboxId).toBe('2');
    const clientAccounts =
      await service.getEmailAccountBySmartleadClientId('client-1');
    expect(clientAccounts.map((account) => account.smartleadInboxId)).toEqual([
      '1',
      '2',
    ]);
    await expect(service.getEmailAccount('nope')).rejects.toThrow(
      NotFoundException,
    );
  });

  it('lists the accounts with pagination', async () => {
    await saveInbox({ id: '1', email: 'one@domain-a.com' });
    await saveInbox({ id: '2', email: 'two@domain-b.com' });
    await saveInbox({ id: '3', email: 'three@domain-c.com' });

    const all = await service.getAllEmailAccounts();
    expect(all).toHaveLength(3);
    const firstPage = await service.getAllEmailAccounts({
      page: 0,
      pageSize: 2,
    });
    expect(firstPage.map((account) => account.smartleadInboxId)).toEqual([
      '1',
      '2',
    ]);
    const secondPage = await service.getAllEmailAccounts({
      page: 1,
      pageSize: 2,
    });
    expect(secondPage.map((account) => account.smartleadInboxId)).toEqual(['3']);
  });

  it('deletes an account', async () => {
    await saveInbox({ id: '1', email: 'one@domain-a.com' });
    const res = await service.deleteEmailAccount('1');
    expect(res.message).toBe('Email account deleted successfully');
    expect(datastore.documents.has('1')).toBe(false);
    await expect(service.deleteEmailAccount('1')).rejects.toThrow(
      NotFoundException,
    );
  });

  it('associates inboxes with a campaign idempotently and dedupes the request', async () => {
    await saveInbox({ id: '1', email: 'one@domain-a.com' });
    await saveInbox({ id: '2', email: 'two@domain-b.com' });

    const associated = await service.associateEmailAccountsWithCampaign({
      emailAccountIds: ['1', '1', '2'],
      campaignId: 'campaign-1',
    });
    expect(associated).toHaveLength(2);
    expect(associated[0].campaignIds).toEqual(['campaign-1']);
    expect(associated[0].numberOfCampaignAssociated).toBe(1);

    await service.associateEmailAccountsWithCampaign({
      emailAccountIds: ['1'],
      campaignId: 'campaign-1',
    });
    const reloaded = await service.getEmailAccount('1');
    expect(reloaded.campaignIds).toEqual(['campaign-1']);
    expect(reloaded.numberOfCampaignAssociated).toBe(1);

    await service.associateEmailAccountsWithCampaign({
      emailAccountIds: ['1'],
      campaignId: 'campaign-2',
    });
    expect((await service.getEmailAccount('1')).numberOfCampaignAssociated).toBe(
      2,
    );
  });

  it('rejects the whole association request when an inbox is missing', async () => {
    await saveInbox({ id: '1', email: 'one@domain-a.com' });
    datastore.store.mockClear();

    await expect(
      service.associateEmailAccountsWithCampaign({
        emailAccountIds: ['1', 'missing'],
        campaignId: 'campaign-1',
      }),
    ).rejects.toThrow(NotFoundException);
    expect(datastore.store).not.toHaveBeenCalled();
    expect((await service.getEmailAccount('1')).campaignIds).toEqual([]);
  });

  it('computes the number of inboxes needed with a floor', () => {
    expect(
      service.getNumberOfEmailAccountsNeeded({
        totalNumberOfEmailsToSend: 600,
        numberOfDaysInCampaign: 10,
        numberOfEmailsPerInboxPerDay: 20,
      }),
    ).toBe(3);
    expect(
      service.getNumberOfEmailAccountsNeeded({
        totalNumberOfEmailsToSend: 500,
      }),
    ).toBe(2);
    expect(
      service.getNumberOfEmailAccountsNeeded({
        totalNumberOfEmailsToSend: 100,
      }),
    ).toBe(0);
  });

  it('ranks the inboxes of the smartlead client', async () => {
    // Same domain twice so the domain tie breaker kicks in.
    await saveInbox({
      id: '1',
      email: 'one@shared.com',
      warmupReputation: 100,
      createdAt: '2024-01-01T00:00:00.000Z',
    });
    await saveInbox({
      id: '2',
      email: 'two@shared.com',
      warmupReputation: 100,
      createdAt: '2023-01-01T00:00:00.000Z',
    });
    await saveInbox({
      id: '3',
      email: 'three@solo.com',
      warmupReputation: 100,
      createdAt: '2024-06-01T00:00:00.000Z',
    });
    await saveInbox({
      id: '4',
      email: 'four@low.com',
      warmupReputation: 96,
      createdAt: '2020-01-01T00:00:00.000Z',
    });
    await saveInbox({
      id: '5',
      email: 'five@other-client.com',
      warmupReputation: 100,
      smartleadClientId: 'client-2',
      createdAt: '2019-01-01T00:00:00.000Z',
    });
    // Inbox 1 is already busy with a campaign so it drops behind inbox 2.
    await service.associateEmailAccountsWithCampaign({
      emailAccountIds: ['3'],
      campaignId: 'other-campaign',
    });

    const best = await service.getBestEmailAccountsForCampaign({
      smartleadClientId: 'client-1',
      campaignId: 'campaign-1',
      totalNumberOfEmailsToSend: 800,
      numberOfDaysInCampaign: 10,
      numberOfEmailsPerInboxPerDay: 20,
    });
    expect(best.map((account) => account.smartleadInboxId)).toEqual([
      '3',
      '2',
      '1',
      '4',
    ]);

    const smaller = await service.getBestEmailAccountsForCampaign({
      smartleadClientId: 'client-1',
      campaignId: 'campaign-1',
      totalNumberOfEmailsToSend: 400,
    });
    expect(smaller.map((account) => account.smartleadInboxId)).toEqual([
      '3',
      '2',
    ]);
  });

  it('ranks accounts with unknown scores last', () => {
    const ranked = EmailAccount.rankEmailAccounts([
      new EmailAccount({ smartleadInboxId: '1', email: 'a@a.com' }),
      new EmailAccount({
        smartleadInboxId: '2',
        email: 'b@b.com',
        deliverabilityScore: 10,
      }),
    ]);
    expect(ranked.map((account) => account.smartleadInboxId)).toEqual([
      '2',
      '1',
    ]);
  });
});

