/**
 * Imports the warmed inboxes of a smartlead client into the email account
 * datastore.
 *
 * Usage:
 *   SMARTLEAD_REPORT_API_KEY=... API_KEY=... SMARTLEAD_CLIENT_ID=22 \
 *     node client/tools/importEmailAccounts.js
 */
//eslint-disable-next-line
const { fetch } = require('cross-fetch');

const SMARTLEAD_API_KEY = process.env.SMARTLEAD_REPORT_API_KEY;
const API_KEY = process.env.API_KEY;
const SMARTLEAD_CLIENT_ID = process.env.SMARTLEAD_CLIENT_ID;
const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';
const PAGE_SIZE = 100;

const getSmartleadInboxes = async () => {
  const inboxes = [];
  let offset = 0;
  // The smartlead email account list endpoint is paginated.
  // eslint-disable-next-line no-constant-condition
  while (true) {
    const url = `https://server.smartlead.ai/api/v1/email-accounts/?api_key=${SMARTLEAD_API_KEY}&offset=${offset}&limit=${PAGE_SIZE}`;
    const res = await fetch(url);
    if (!res.ok) {
      throw new Error(`Failed to list smartlead inboxes: ${res.status}`);
    }
    const page = await res.json();
    if (!Array.isArray(page) || page.length === 0) {
      break;
    }
    inboxes.push(...page);
    if (page.length < PAGE_SIZE) {
      break;
    }
    offset += PAGE_SIZE;
  }
  return inboxes;
};

const saveEmailAccount = async (inbox) => {
  const res = await fetch(`${BASE_URL}/emailinfra/email-accounts`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-API-KEY': API_KEY,
    },
    body: JSON.stringify({
      smartleadInboxId: `${inbox.id}`,
      email: inbox.from_email,
      smartleadClientId: `${SMARTLEAD_CLIENT_ID || inbox.client_id}`,
      tags: (inbox.tags || []).map((tag) =>
        typeof tag === 'string' ? tag : tag && tag.name,
      ),
    }),
  });
  if (!res.ok) {
    console.error(`Failed to import inbox ${inbox.id}: ${res.status}`);
    return null;
  }
  return res.json();
};

const run = async () => {
  const inboxes = await getSmartleadInboxes();
  const clientInboxes = SMARTLEAD_CLIENT_ID
    ? inboxes.filter(
        (inbox) => `${inbox.client_id}` === `${SMARTLEAD_CLIENT_ID}`,
      )
    : inboxes;
  console.log(`Importing ${clientInboxes.length} inboxes`);
  for (const inbox of clientInboxes) {
    const emailAccount = await saveEmailAccount(inbox);
    if (emailAccount) {
      console.log(
        `Imported ${emailAccount.email} (${emailAccount.smartleadInboxId}): ${emailAccount.deliverabilityScore} ${emailAccount.deliverabilityScoreBand}`,
      );
    }
  }
};

run().catch((error) => {
  console.error(error);
  process.exit(1);
});

/**
 * Re-reads the warm up reputation (deliverability score) of every stored inbox
 * from smartlead and persists it again.
 *
 * Usage:
 *   API_KEY=... node client/tools/syncEmailAccountReputation.js
 */
//eslint-disable-next-line
const { fetch } = require('cross-fetch');

const API_KEY = process.env.API_KEY;
const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';
const PAGE_SIZE = 100;

const headers = {
  'Content-Type': 'application/json',
  'X-API-KEY': API_KEY,
};

const listEmailAccounts = async (page) => {
  const res = await fetch(
    `${BASE_URL}/emailinfra/email-accounts?page=${page}&pageSize=${PAGE_SIZE}`,
    { headers },
  );
  if (!res.ok) {
    throw new Error(`Failed to list email accounts: ${res.status}`);
  }
  return res.json();
};

const syncEmailAccount = async (emailAccount) => {
  const res = await fetch(`${BASE_URL}/emailinfra/email-accounts`, {
    method: 'POST',
    headers,
    body: JSON.stringify({
      smartleadInboxId: emailAccount.smartleadInboxId,
      email: emailAccount.email,
      smartleadClientId: emailAccount.smartleadClientId,
      tags: emailAccount.tags,
      campaignIds: emailAccount.campaignIds,
    }),
  });
  if (!res.ok) {
    console.error(
      `Failed to sync inbox ${emailAccount.smartleadInboxId}: ${res.status}`,
    );
    return null;
  }
  return res.json();
};

const run = async () => {
  let page = 0;
  let synced = 0;
  // eslint-disable-next-line no-constant-condition
  while (true) {
    const emailAccounts = await listEmailAccounts(page);
    if (!Array.isArray(emailAccounts) || emailAccounts.length === 0) {
      break;
    }
    for (const emailAccount of emailAccounts) {
      const updated = await syncEmailAccount(emailAccount);
      if (updated) {
        synced += 1;
        console.log(
          `${updated.email} (${updated.smartleadInboxId}): ${updated.deliverabilityScore} ${updated.deliverabilityScoreBand}`,
        );
      }
    }
    if (emailAccounts.length < PAGE_SIZE) {
      break;
    }
    page += 1;
  }
  console.log(`Synced ${synced} email accounts`);
};

run().catch((error) => {
  console.error(error);
  process.exit(1);
});

